#include <cstddef>
#include <cstdint>
static std::size_t put_i64(std::int64_t x,std::uint8_t*out,std::size_t p){if(x<0){out[p++]='-';x=-x;}std::uint8_t d[20];std::size_t n=0;do{d[n++]=static_cast<std::uint8_t>('0'+x%10);x/=10;}while(x);while(n)out[p++]=d[--n];return p;}
extern "C" std::int64_t number_container_system(const std::int64_t*v,std::size_t n,std::uint8_t*out,std::size_t cap){if(!v||n<1||v[0]<0||v[0]>32||n!=1+3*static_cast<std::size_t>(v[0]))return -1;std::int64_t values[64]={};bool present[64]={};std::uint8_t buf[128];std::size_t used=0;for(std::size_t i=0;i<static_cast<std::size_t>(v[0]);i++){auto op=v[1+3*i],a=v[2+3*i],b=v[3+3*i];if(op==0){if(a<0||a>63||b< -100||b>100)return -1;values[a]=b;present[a]=true;}else if(op==1){if(a< -100||a>100||b!=0)return -1;std::int64_t found=-1;for(std::int64_t j=0;j<64;j++)if(present[j]&&values[j]==a){found=j;break;}if(used)buf[used++]=',';used=put_i64(found,buf,used);}else return -1;}if(used>cap||(used&&!out))return -2;for(std::size_t i=0;i<used;i++)out[i]=buf[i];return static_cast<std::int64_t>(used);}
